-- 1161: Injection and structural foam calculators, version 4, and the LSR calculator, version 2 -- the pack and cure constants from stated sources.
--
-- GENERATED by scripts/generate-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/calculators/plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- The pack phase was 35 % of the cooling time with a 2 s floor, called the Menges gate-freeze rule; no published source gives either number (research
-- of 2026-11-25). The floor is now Moldflow's default hold time, the greater of 2 x the injection time and 1 s (patent US 7,037,452 B1), and the ratio
-- the closest published figure, 0.20: holding 10 % and cooling 50 % of the cycle (Priamus patent US 7,931,837 B2). The liquid silicone cure was
-- 0.008 x exp(3500 / T) x wall, 18.1 s per mm at 180 C, cited to "Ossipov et al., Polymer Engineering 2002", which could not be found anywhere; Dow
-- gives 3-5 s per mm as the standard vulcanization time (XIAMETER LSR injection molding guide, p. 13), so A is 0.0022 (5 s per mm at 180 C) with
-- Ea/R kept. Each constant's source is in the spec (its note). A part that cools long holds for less (20 % of cooling, not 35 %); one that fills
-- slowly holds for 2 x its fill time (the worked mirror cover: 2 s -> 5.38 s); an LSR part cures in about a quarter of the time.
-- Replaced under a new version (a calculator in use is not edited in place).
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Cycle Time
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Cycle Time$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description, version)
    VALUES (NULL, $q$Injection Molding - Cycle Time$q$, 'process', 'single', false, true, true, $q$Injection cycle time = (Fill + Pack + Cooling + Mold open/close) x Cycle Time Adjustment Factor (formula registry F-08, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula). Fill = shot melt volume / the press injection rate x the injectionTimeAdjustmentFactors for cavities and gates (F-05, VALIDATED). Pack = 20 % of cooling, at least the larger of 2 x the fill time and 1 s (F-06 version 2, ASSUMED: the reference holds no hold time; closest published basis for the 20 %: the Priamus patent US 7,931,837 B2, hold 10 % and cooling 50 % of the cycle; the floor is Moldflow's default hold, US 7,037,452 B1, "the greater of 2 times injection time and one second"). Mold open/close = the press Euromap 6 dry cycle (F-07, VALIDATED). Not modelled, because the reference has no formula or press data: ejector travel, plasticizing, part and material handling, slides and lifters. Rounded as the engine does: cooling and pack to 0.1 s, fill and the total to 0.01 s. (Version 4, migration 1161: the pack was 35 % of cooling with a 2 s floor.)$q$, 4)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Injection cycle time = (Fill + Pack + Cooling + Mold open/close) x Cycle Time Adjustment Factor (formula registry F-08, ASSUMED). Cooling is the Menges plate-cooling equation, t = s^2 / (pi^2 alpha) x ln((4/pi)(Tm - Tw)/(Te - Tw)), alpha = k / (rho cp) (F-04, ASSUMED: memory/ holds no cooling formula). Fill = shot melt volume / the press injection rate x the injectionTimeAdjustmentFactors for cavities and gates (F-05, VALIDATED). Pack = 20 % of cooling, at least the larger of 2 x the fill time and 1 s (F-06 version 2, ASSUMED: the reference holds no hold time; closest published basis for the 20 %: the Priamus patent US 7,931,837 B2, hold 10 % and cooling 50 % of the cycle; the floor is Moldflow's default hold, US 7,037,452 B1, "the greater of 2 times injection time and one second"). Mold open/close = the press Euromap 6 dry cycle (F-07, VALIDATED). Not modelled, because the reference has no formula or press data: ejector travel, plasticizing, part and material handling, slides and lifters. Rounded as the engine does: cooling and pack to 0.1 s, fill and the total to 0.01 s. (Version 4, migration 1161: the pack was 35 % of cooling with a 2 s floor.)$q$, version = 4, updated_at = now() WHERE id = v_id;
  END IF;

